"""Build the static wiki. Run from any directory with Python 3.9+. No dependencies."""
from pathlib import Path
import json, html
R=Path(__file__).resolve().parents[1]
def write(p,s):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
def esc(s):return html.escape(str(s),quote=True)
def a(url,label):return f'<a href="{esc(url)}">{label}</a>'
NAV=[('index.html','產業總覽','01'),('sectors/endpoint.html','端點安全','02'),('sectors/identity.html','身分安全','03'),('companies/crwd.html','CrowdStrike','CRWD'),('companies/okta.html','Okta','OKTA'),('companies/panw.html','Palo Alto Networks','PANW'),('metrics/index.html','財報指標','04')]
source_urls={t:[q['source_urls'][0] for q in json.loads((R/f'data/companies/{t}.json').read_text())['quarters']] for t in ['crwd','okta','panw']}
SITE='https://howardchiang0129.github.io/cybersecurity-research-wiki/'
REPO='https://github.com/howardchiang0129/cybersecurity-research-wiki'
def shell(path,title,eyebrow,subtitle,body,toc=()):
 pre='' if '/' not in path else '../'
 nav=""
 for p,n,code in NAV:
  current='aria-current="page"' if path==p else ""
  nav+=f'<a {current} href="{pre+p}"><span>{n}</span><small>{code}</small></a>'
 contents=''.join(a('#'+k,v) for k,v in toc)
 return f'''<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(subtitle)}"><title>{esc(title)}｜資安研究室</title><link rel="icon" href="{pre}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{pre}assets/css/style.css"><script defer src="{pre}assets/js/app.js"></script></head><body><a class="skip" href="#main">跳至主要內容</a><aside class="sidebar"><a class="brand" href="{pre}index.html"><span class="brandmark">C<span>／</span>R</span><span>資安研究室<small>CYBER RESEARCH WIKI</small></span></a><div class="edition">FIELD NOTES <span>VOL. 01 / 2026</span></div><nav aria-label="主選單"><p class="navlabel">從產業到公司</p>{nav}</nav><div class="sidebar-bottom"><span class="status-dot"></span> 持續擴充的研究筆記<p>先理解產品，再閱讀數字。</p><a href="{pre}AGENTS.md">閱讀 AI 協作規則 ↗</a><a href="{REPO}" target="_blank" rel="noopener">GitHub 完整專案 ↗</a></div></aside><div class="workspace"><header class="topbar"><span>資安產業研究入門百科</span><div><label class="sr-only" for="site-search">搜尋主題或公司</label><input id="site-search" type="search" placeholder="搜尋主題、公司、縮寫…" autocomplete="off"><button id="menu-toggle" aria-expanded="false" aria-label="開啟導覽">目錄</button></div><div id="search-results" hidden></div></header><main id="main"><div class="page-top"><span class="eyebrow">{eyebrow}</span><span class="meta">編輯核對 2026.11.16</span></div><section class="page-heading"><h1>{title}</h1><p class="lead">{subtitle}</p></section>{f'<nav class="contents" aria-label="本頁目錄">{contents}</nav>' if toc else ''}{body}<footer><span>資安研究室 <small>CYBER RESEARCH WIKI</small></span><p>公開資料整理與學習筆記。財務數據以各公司財季為準；資料狀態與來源詳見各頁。</p><a href="{pre}AGENTS.md">協作規則</a> · <a href="{pre}README.md">專案說明</a> · <a href="{pre}CHANGELOG.md">更新紀錄</a><span class="footer-no">RESEARCH / UNDERSTAND / CONNECT</span></footer></main></div></body></html>'''
def section(id,title,text):return f'<section class="article-section" id="{id}"><h2>{title}</h2>{text}</section>'
def paras(*xs):return ''.join('<p>'+x+'</p>' for x in xs)
def cards(items):return '<div class="cards">'+''.join(f'<article class="note-card"><span class="card-index">{i+1:02}</span><h3>{t}</h3><p>{b}</p></article>' for i,(t,b) in enumerate(items))+'</div>'
def sources(items):return '<div class="source-list">'+''.join(f'<a href="{esc(u)}" target="_blank" rel="noopener"><span>{n}</span><span>官方來源 ↗</span></a>' for n,u in items)+'</div><p class="fine">最後核對：2026-11-16。網站內容為自行整理的教學摘要，並非官方網站。</p>'
home='''<div class="hero-panel"><div><span class="pill">從零開始，建立研究框架</span><h2>看懂資安，<br>從保護什麼開始。</h2><p>把產品縮寫、企業需求與財報數字連起來。<br>一份可以逐季更新、持續生長的產業筆記。</p><a class="button" href="sectors/endpoint.html">開始閱讀端點安全 <span>↗</span></a></div><div class="system-map" aria-label="企業安全由端點、身分、網路、雲端及資料等層次組成"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="map-center">企業<br><small>數位資產</small></div><span class="map-label label-one">端點 ENDPOINT</span><span class="map-label label-two">身分 IDENTITY</span><span class="map-label label-three">網路 NETWORK</span><span class="map-label label-four">雲端 CLOUD</span><span class="map-caption">多層防護 · 沒有單一萬靈丹</span></div></div><div class="overview-strip"><div><b>02</b><span>領域入門</span></div><div><b>03</b><span>公司研究</span></div><div><b>12</b><span>季度資料紀錄</span></div><div><b>01</b><span>共用協作規則</span></div></div>'''
home+=section('start','一條清楚的學習路線',cards([('理解企業風險','先問保護的是裝置、身分還是資料，再對應攻擊情境與需要的產品。'),('辨識公司定位','研究 CRWD、OKTA 與 PANW，了解專精領域、跨產品競爭及平台整合。'),('用數字驗證','閱讀營收、ARR、RPO 與現金流，區分產品故事、營運成果與官方財測。')]))
home+=section('sectors','資安預算，花在哪裡？','<p>企業通常同時使用多家供應商。下列分類是理解需求的入口，產品邊界會重疊。</p><div class="sector-grid">'+''.join(f'<{("a href="+chr(34)+u+chr(34)) if u else "article"} class="sector-tile {"available" if u else "planned"}"><span class="eyebrow">{en}</span><h3>{zh} <span>{"↗" if u else ""}</span></h3><p>{desc}</p><small>{"閱讀入門" if u else "概念導讀 · 獨立頁尚未建立"}</small></{"a" if u else "article"}>' for en,zh,desc,u in [('ENDPOINT','端點安全','員工電腦或伺服器出現惡意程式時，如何偵測並隔離？','sectors/endpoint.html'),('IDENTITY','身分安全','誰可以登入、可以使用什麼權限，又何時應撤銷？','sectors/identity.html'),('NETWORK','網路與安全存取','控管連線與流量，讓遠端員工安全使用企業資源。',None),('CLOUD','雲端安全','降低設定錯誤、過度權限與工作負載遭入侵的風險。',None),('SECURITY OPERATIONS','安全營運','整合警訊、調查事件並協調回應，協助 SOC 日常運作。',None),('DATA','資料安全與復原','防止敏感資料外流，並在事故後恢復關鍵營運。',None)])+'</div>')
home+=section('companies','從產品走向公司','<div class="company-list">'+''.join(f'<a href="companies/{t}.html"><span class="ticker {t}">{t.upper()}</span><div><h3>{name}</h3><p>{desc}</p></div><span class="arrow">↗</span></a>' for t,name,desc in [('crwd','CrowdStrike','從端點出發，擴展 Falcon 平台與多模組採用。'),('okta','Okta','從登入驗證到權限治理，理解身分安全的價值。'),('panw','Palo Alto Networks','跨網路、雲端、安全營運與身分的整合型供應商。')])+'</div>')
home+=section('buying','誰決定企業的資安採購？',paras('資安長（CISO）與安全團隊通常提出風險與技術需求，IT、雲端或身分團隊參與部署，採購與財務部門評估預算、合約及總持有成本。產品測試、既有系統整合與續約時點，都可能影響成交速度。','<strong>研究觀察：</strong>預算具有持續性，不代表成長不受景氣影響。新專案可能延後，客戶也可能減少席次、整併工具或改變付款方式。雲端化、合規與 AI 應用擴張帶來新需求，但採購是否轉成收入仍需由財報驗證。'))
home+=section('updates','資料怎麼保持可追蹤？','<div class="callout"><strong>每季追加，保留歷史。</strong><p>三家公司各收錄最近四個已公布季度，截至日皆為 2026-07-31。部分延伸欄位仍待核對，請以公司頁標記為準。AGENTS.md 規定更新來源、期間、單位與異動紀錄；本網站未啟用自動更新排程。</p><a href="AGENTS.md">查看完整更新規則 ↗</a></div>'+sources([('NIST：Zero Trust Architecture','https://www.nist.gov/publications/zero-trust-architecture'),('NIST：Zero Trust 實作架構','https://pages.nist.gov/zero-trust-architecture/VolumeB/architecture.html')]))
write('index.html',shell('index.html','資安，從這裡讀起。','THE RESEARCH DESK / 產業總覽','從企業需要保護什麼，到公司如何創造收入。建立你的第一套資安產業研究框架。',home))
sector_data={
'endpoint':{'title':'端點安全','en':'ENDPOINT SECURITY','intro':'從一台員工筆電開始，理解偵測、調查與回應如何串成一道防線。','definition':'端點安全保護筆電、桌機與伺服器等裝置，降低惡意程式與入侵活動造成的損害。','pain':'員工點開偽裝的附件後，攻擊者可能在電腦執行指令、竊取登入資訊，甚至向其他系統移動。只辨識已知病毒，通常不足以應付完整的攻擊過程。','scenario':'假設財務人員開啟偽造帳單。端點代理程式發現文件啟動異常程序、連向可疑網域，安全團隊調查程序關係與行為紀錄，必要時將該裝置與網路隔離。這是教學情境，不代表所有產品都能阻擋每次攻擊。','flow':[('蒐集','代理程式觀測程序、檔案及裝置活動。'),('偵測','以規則、已知威脅與行為分析識別異常。'),('調查與回應','追查事件脈絡，依權限隔離裝置或終止程序。')],'terms':[('EPP','Endpoint Protection Platform','端點防護平台，著重預防與阻擋惡意活動。'),('EDR','Endpoint Detection and Response','端點偵測與回應，重點在裝置活動可視性、調查與處置。'),('XDR','Extended Detection and Response','跨端點、身分或其他來源連結訊號，定義與涵蓋範圍因供應商而異。'),('MDR','Managed Detection and Response','委由服務團隊協助監控、調查與回應；屬交付服務方式，不等於一套 EDR 軟體。')],'difference':'EPP 與 EDR 常被整合在同一平台。EDR 以端點遙測為核心，XDR 擴展跨來源關聯；SIEM 偏重集中管理與分析多來源事件。產品重疊不代表功能與部署方式相同。','vendors':'CRWD 的 Falcon 是本百科的公司研究範例；PANW 的 Cortex 也參與偵測與回應領域。比較時應看實際模組與部署範圍。','model':'常見方式是按受保護裝置數、產品模組與合約期間收費，也可能搭配代管服務。實際價格取決於方案與協商。','watch':'追蹤 ARR、Net New ARR、模組採用率、訂閱毛利率及續約表現。ARR 成長需區分新客、擴充與價格效果；模組數增加也不一定等於相同比例收入增加。','risk':'部署品質、誤報、服務中斷與產品更新可能影響客戶信任；平台綁售與客戶工具整併會改變競爭。','related':[('CrowdStrike 公司研究','../companies/crwd.html'),('PANW 公司研究','../companies/panw.html')], 'sources':[('CrowdStrike：季度財報與平台採用',source_urls['crwd'][-1]),('NIST：端點監控與架構','https://pages.nist.gov/zero-trust-architecture/VolumeB/architecture.html')]},
'identity':{'title':'身分安全','en':'IDENTITY SECURITY','intro':'登入成功只是起點。更重要的是：誰能做什麼，以及這份權限何時應該結束。','definition':'身分安全管理人員、服務與其他數位身分的驗證和存取權限，降低帳號遭冒用與權限濫用的風險。','pain':'企業同時使用多套 SaaS 與內部系統。若帳號開通、調職與離職權限沒有同步管理，過期帳號或過度授權可能留下風險。','scenario':'一名員工離職後，企業需要停用登入、撤銷應用權限並檢查特權存取，而非只關閉電子郵件。若是 AI Agent，也要定義擁有者、可用資源與可執行動作。此為教學情境。','flow':[('確認身分','透過登入與驗證因子確認存取者。'),('判斷權限','依角色、政策與風險決定可使用的資源。'),('持續治理','記錄存取、檢視權限並在生命週期結束時撤銷。')],'terms':[('SSO','Single Sign-On','單一登入，減少在不同應用重複輸入帳密。'),('MFA','Multi-Factor Authentication','多因素驗證，使用不同類型的驗證因子；不同 MFA 的抗釣魚能力不相同。'),('IAM','Identity and Access Management','身分與存取管理，涵蓋身分驗證及存取政策。'),('PAM','Privileged Access Management','特權存取管理，控管高權限帳號、憑證與工作階段。'),('IGA','Identity Governance and Administration','身分治理與管理，著重誰應擁有哪些權限、審查與生命週期。')],'difference':'驗證回答「你是誰」，授權回答「你能做什麼」，治理回答「這些權限是否合理」。PAM 著重高權限風險，IGA 著重權限治理，企業可能同時需要多種能力。','vendors':'OKTA 是本百科的身分研究範例。PANW 的產品版圖也已涵蓋身分安全；比較時應分清員工身分、客戶身分與特權存取的採購需求。','model':'員工身分常依使用者與功能模組收費；客戶身分可能依月活躍使用者及方案計費。AI Agent 與非人類身分的商業模式仍需追蹤實際產品與合約。','watch':'觀察訂閱收入、RPO、cRPO、留存率與大型客戶表現。cRPO 是未來十二個月預期認列的訂閱合約餘額，不等於下一年保證實現的收入。','risk':'平台商綁售、服務可用性與資安事件可能影響競爭；身分數增加也未必立刻轉成付費需求。','related':[('Okta 公司研究','../companies/okta.html'),('PANW 公司研究','../companies/panw.html')],'sources':[('NIST：Zero Trust 原則','https://www.nist.gov/publications/zero-trust-architecture'),('CISA：抗釣魚 MFA','https://www.cisa.gov/sites/default/files/publications/fact-sheet-implementing-phishing-resistant-mfa-508c.pdf'),('Okta：季度財報',source_urls['okta'][-1])]}}
for slug,d in sector_data.items():
 body='<div class="definition"><span>一句話理解</span><p>'+d['definition']+'</p></div>'
 body+=section('problem','企業遇到什麼問題？',paras(d['pain'])+'<div class="scenario"><span class="eyebrow">使用情境 / ILLUSTRATION</span><p>'+d['scenario']+'</p></div>')
 body+=section('how','產品如何運作？',cards(d['flow']))
 body+=section('terms','先認識這幾個名詞','<div class="term-list">'+''.join(f'<article><b>{abbr}</b><div><h3>{full}</h3><p>{desc}</p></div></article>' for abbr,full,desc in d['terms'])+'</div>'+paras(d['difference']))
 body+=section('business','從產品看商業模式',paras(d['model'],d['vendors']))
 body+=section('watch','研究時追蹤什麼？',paras(d['watch'])+'<div class="callout"><strong>需要同時觀察的風險</strong><p>'+d['risk']+'</p></div>')
 body+=section('related','接著閱讀','<div class="related">'+''.join(a(u,n+' ↗') for n,u in d['related'])+a('../metrics/index.html','資安財報指標 ↗')+'</div>')
 body+=section('sources','資料來源',sources(d['sources']))
 write('sectors/'+slug+'.html',shell('sectors/'+slug+'.html',d['title'],d['en']+' / 領域入門',d['intro'],body,[('problem','企業痛點'),('how','運作方式'),('terms','核心名詞'),('business','商業模式'),('watch','追蹤指標'),('sources','資料來源')]))
companies={
'crwd':{'name':'CrowdStrike','en':'ENDPOINT / CLOUD / SECURITY OPERATIONS','intro':'以 Falcon 平台為核心，從端點防護延伸到雲端、身分與安全營運。','position':'企業可先部署端點防護與偵測，再依需求加入更多模組。分析重點在平台採用如何轉化為訂閱合約與現金流。','use':'安全團隊調查員工電腦上的異常活動，並串接身分、雲端或其他訊號，追查是否屬於同一次攻擊。','products':[('Falcon 與端點','以裝置遙測、威脅偵測與回應作為切入點。'),('擴展平台','雲端、身分與 Next-Gen SIEM 等產品拓展原有客戶需求。'),('Falcon Flex','提供產品採用的商業彈性；應分開追蹤採用客戶與收入貢獻。')],'pricing':'訂閱通常與端點數、模組與合約期間相關，也提供事件回應等專業服務。不同模組可能有不同計價方式。','competition':'端點採購可能與 Microsoft、PANW 等方案比較；在 SIEM 與雲端安全領域又會遇到不同競爭者。部分合作夥伴同時也有自己的資安產品。','moat':'研究判斷：裝置部署基礎、威脅資料與安全團隊工作流程有助提高整合價值；是否形成轉換成本，仍要用續約及擴充表現驗證。','growth':'研究觀察：新客戶、多模組採用及既有客戶跨產品擴充，是值得追蹤的收入來源。AI 安全需求應以實際付費合約驗證。','risk':'平台競爭、客戶預算整併、服務可靠性與事件相關費用，都可能影響需求、成本或信任。高現金流不代表沒有股權稀釋成本。','latest':'FY2027 Q2 的 ARR 為 5,840，Net New ARR 為 332.8。觀察新增合約能否持續支持收入，而不是只看當季模組數。公司當季仍有 GAAP 營業虧損，non-GAAP 盈利需連同調整項目閱讀。','link':'endpoint','fy':'1 月 31 日','fcf_note':'FCF 採公司定義，除資產支出外也含資本化軟體及遞延薪酬投資淨額等項目，不能簡化為只扣硬體 CapEx。SBC 純額尚未核對；含雇主稅的調整金額不冒充純 SBC。'},
'okta':{'name':'Okta','en':'WORKFORCE / CUSTOMER / IDENTITY GOVERNANCE','intro':'用獨立的身分平台，管理誰能登入，以及誰可以存取哪些企業資源。','position':'涵蓋員工與客戶身分需求。理解公司時，先區分內部員工登入與面向終端客戶的身分基礎設施。','use':'員工使用同一個身分登入多套應用，企業在調職、離職或風險增加時調整其存取權限。','products':[('Workforce Identity','支援員工登入驗證、應用存取與身分生命週期。'),('Customer Identity / Auth0','協助開發者把登入、驗證等能力接入客戶應用。'),('Governance 與 Privileged Access','將權限治理與高權限存取納入更多身分管理需求。')],'pricing':'員工身分常依使用者及功能計費；客戶身分常涉及月活躍使用者與方案。合約與使用者組合會影響收入成長。','competition':'Microsoft 等平台商在員工身分領域具有既有通路；PAM、IGA 與客戶身分又有不同的專精競爭者。比較須以採購用途為單位。','moat':'研究判斷：跨應用整合、中立定位與身分政策部署，有機會提高客戶黏著度；同時要觀察平台商綁售對價格及新客戶的影響。','growth':'研究觀察：大型客戶、新產品採用與客戶身分業務值得追蹤。AI Agent 需要身分與權限控制，但商機大小仍取決於產品採用及實際計價。','risk':'服務中斷或資安事件可能影響信任；綁售、席次調整與採購延遲會影響成長。專業服務轉向合作夥伴也可能改變收入組合。','latest':'FY2027 Q2 營收年增 11%，cRPO 年增 14%。研究上可追蹤訂閱合約動能能否轉化為收入；FCF 也會受收款與支出時點影響，不能單季直接年化。','link':'identity','fy':'1 月 31 日','fcf_note':'FCF 採公司定義，扣除不動產設備淨購置與資本化軟體。FY2027 non-GAAP 稅率改為 21%，比較 EPS 時需注意稅率影響。'},
'panw':{'name':'Palo Alto Networks','en':'NETWORK / CLOUD / SOC / IDENTITY','intro':'從網路防火牆起家，擴展成跨多個資安領域的整合型供應商。','position':'研究焦點是平台整合如何帶動跨產品採用，以及併購之後的成長與獲利口徑如何變化。','use':'企業希望整合網路存取、防護政策與事件調查，減少不同工具之間的資料與操作斷點；實際效益仍需評估導入與遷移成本。','products':[('Network & AI Security','從防火牆到安全存取，保護流量與企業應用連線。'),('Cortex 與雲端安全','包含偵測、回應、安全營運及雲端相關能力；產品歸屬須依最新公告查核。'),('Idira 與身分布局','最新財報列示身分平台，併購整合使產品與財務比較更需注意範圍。')],'pricing':'同時包含產品銷售、訂閱與支援，依設備、功能、使用者或其他使用規模計費。收入組合與合約期間會影響 RPO 與收入認列。','competition':'網路安全、端點與安全營運領域分別面對不同競爭者；CRWD 在部分偵測與營運產品有重疊，OKTA 的身分需求也未必與所有 PAM 產品直接替代。','moat':'研究判斷：產品廣度、通路與既有客戶基礎有助交叉銷售。平台價值需由客戶採用、續約與部署成果驗證，也要考慮整合成本與單一供應商集中風險。','growth':'研究觀察：NGS ARR、平台整合、AI 安全與新增產品是重要追蹤線索。總營收及 ARR 的成長要拆分有機與併購貢獻。','risk':'大型併購整合、產品重疊、遷移優惠與費用調整，可能使營收、GAAP 獲利與現金流不同步。NGS ARR 並不是全公司總 ARR。','latest':'FY2026 Q4 營收為 3,410、NGS ARR 為 9,100。GAAP EPS 為負、non-GAAP EPS 為正，差異包含股權薪酬、併購及其他調整，應查看官方調節表。','link':'endpoint','fy':'7 月 31 日','fcf_note':'本頁 FCF 為公司定義的 CFO 減資產支出；Adjusted FCF 另加回特定支出。兩者與全年、TTM 利潤率不得混用。Q3 起併購影響比較，總成長率不等於有機成長率。'}}
for t,d in companies.items():
 data=json.loads((R/f'data/companies/{t}.json').read_text());q=data['quarters'][-1]
 latest_index=len(data['quarters'])-1
 json_data=json.dumps(data,ensure_ascii=False)
 body=f'<div class="company-intro"><span class="ticker {t}">{t.upper()}</span><p>{d["position"]}</p><span class="pill">財年截止 {d["fy"]}</span></div>'
 body+=section('business','公司在解決什麼問題？',paras(d['use'],d['pricing'])+cards(d['products']))
 body+=section('edge','競爭優勢與成長動能',paras(d['competition'],d['moat'],d['growth'])+'<div class="callout"><strong>主要風險</strong><p>'+d['risk']+'</p></div>')
 body+=section('financials','季度財務與營運數據',f'''<div class="finance-toolbar"><div><label for="quarter-select">選擇財季</label><select id="quarter-select">{''.join(f'<option value="{i}" {"selected" if i==latest_index else ""}>FY{x["fiscal_year"]} Q{x["fiscal_quarter"]}</option>' for i,x in reversed(list(enumerate(data['quarters']))))}</select></div><a class="text-link" href="../data/companies/{t}.json" download>下載完整 JSON ↗</a></div><div id="quarter-meta" class="fine"></div><div id="finance-cards" class="finance-cards" aria-live="polite"></div><div class="financial-detail"><h3>完整財務欄位</h3><div id="finance-details"></div></div><div class="financial-detail"><h3>公司特有指標</h3><div id="kpi-cards" class="kpi-cards"></div></div><p id="quarter-note" class="data-note"></p><div id="quarter-sources" class="source-list"></div><p class="fine">金額單位：百萬美元；EPS：美元／股；股數：百萬股。待核對表示本版尚未完成該欄位查核，不代表公司未揭露。YoY 為官方約數，比率由金額計算時可能有四捨五入差異。</p><noscript><p>請啟用 JavaScript 使用季度切換。也可下載上方 JSON 閱讀全部季度。最新季度營收：{q['revenue']} 百萬美元，YoY：{q['revenue_yoy']}%。</p></noscript><script type="application/json" id="financial-data">{json_data}</script>''')
 body+=section('history','四季營收軌跡','<p class="fine">以各公司自己的財季排序，單位：百萬美元。長條由零起算。</p><div class="revenue-history">'+''.join(f'<div><span>FY{x["fiscal_year"]} Q{x["fiscal_quarter"]}</span><div class="bar-track"><div style="width:{x["revenue"]/max(y["revenue"] for y in data["quarters"])*100:.2f}%"></div></div><b>{x["revenue"]:,.1f}</b></div>' for x in data['quarters'])+'</div>')
 g=data['guidance'];body+=section('guidance','官方財測｜與實績分開閱讀',f'<div class="guidance"><article><span>{g["next_period"]} 營收財測</span><strong>{g["next_revenue"][0]:,.1f}–{g["next_revenue"][1]:,.1f}</strong><small>百萬美元</small></article><article><span>{g["full_period"]} 全年營收財測</span><strong>{g["full_revenue"][0]:,.1f}–{g["full_revenue"][1]:,.1f}</strong><small>百萬美元</small></article></div><p>{g["note"]}</p><p class="fine">發布日 {g["as_of"]} · {a(g["source_url"],"官方財測來源 ↗")}</p>')
 body+=section('reading','最新一季，怎麼讀？',paras(d['latest'],d['fcf_note']))
 body+=section('sources','來源與延伸閱讀',sources([(f'FY{x["fiscal_year"]} Q{x["fiscal_quarter"]} 財報新聞稿',x['source_urls'][0]) for x in reversed(data['quarters'])])+'<div class="related">'+a('../sectors/'+d['link']+'.html','相關領域入門 ↗')+a('../metrics/index.html','財報指標工具箱 ↗')+'</div>')
 write('companies/'+t+'.html',shell('companies/'+t+'.html',d['name'],d['en']+' / 公司研究',d['intro'],body,[('business','產品與模式'),('edge','優勢與風險'),('financials','季度數據'),('history','歷史軌跡'),('guidance','官方財測'),('sources','資料來源')]))
metrics=[('ARR','Annual Recurring Revenue','把期末經常性合約換算成年化規模的營運指標，通常不等於已認列收入。','假設月經常性收入 10，簡化年化 ARR 為 120。','需依公司定義閱讀；PANW 的 NGS ARR 僅涵蓋特定產品。'),('Net New ARR','淨新增年化經常性收入','觀察期末 ARR 相對上期淨增加多少，通常受新客、擴充、流失與其他調整影響。','假設期初 ARR 100、期末 120，簡化淨增加為 20。','匯率、併購或定義變更可能影響，不一定全是當季新簽約。'),('RPO / cRPO','Remaining Performance Obligations','RPO 是尚未履行的合約義務；cRPO 通常是未來十二個月預期認列部分。','假設 RPO 100，其中 60 預計十二個月內認列，cRPO 為 60。','合約期間與付款方式會影響比較；不是當季收入，也不是現金。'),('NRR','Net Revenue Retention','觀察相同既有客戶群的收入或 ARR 在一段期間後保留多少，含擴充、縮減與流失。','假設原客戶群 100，一年後 110，NRR 為 110%。','不包含新客；不同公司採用的收入或 ARR 定義及期間可能不同。'),('Billings','帳單金額／開票指標','常見簡化代理值是營收加遞延收入變動，但應優先採公司定義。','假設營收 100、遞延收入增加 20，簡化 Billings 為 120。','不等於現金收款；付款條款與合約期間會造成波動。'),('FCF Margin','Free Cash Flow Margin','自由現金流除以同期間營收；先確認 FCF 是否含特殊調整。','假設營收 100、FCF 25，FCF Margin 為 25%。','預收款、支出時點與 SBC 會影響判讀；單季不可直接年化。'),('SBC / Dilution','Stock-Based Compensation','股權薪酬是重要報酬成本，應搭配股數變化與回購觀察。','假設獲利不變、股數增加 10%，每股獲利會降低。','non-GAAP 常加回 SBC，但經濟成本不會因此消失；拆股本身不是經濟稀釋。'),('GAAP / non-GAAP','會計準則與調整後指標','GAAP 為會計準則口徑；non-GAAP 依公司調整方式排除部分項目。','假設 GAAP 營業利益 10，加回 SBC 5，簡化調整後為 15。','必須閱讀調節表；各公司排除項目不同，不能只比較表面數字。')]
body='<div class="definition"><span>研究原則</span><p>先確認定義、期間與單位，再比較成長。任何一個數字，都需要放回商業模式裡理解。</p></div>'
body+=section('glossary','八個值得先理解的指標','<div class="metric-glossary">'+''.join(f'<details {"open" if i==0 else ""}><summary><span>{abbr}</span><b>{full}</b><span class="plus">＋</span></summary><div><p>{desc}</p><p><strong>假設範例：</strong>{example}</p><p class="fine">判讀限制：{limit}</p></div></details>' for i,(abbr,full,desc,example,limit) in enumerate(metrics))+'</div>')
body+=section('calculator','用一個例子，理解 FCF Margin','<div class="calculator"><div><span class="eyebrow">互動練習 / 假設數據</span><h3>輸入同一期間的金額</h3><label for="calc-revenue">營收（百萬美元）</label><input id="calc-revenue" type="number" min="0" step="any" value="100"><label for="calc-fcf">自由現金流（百萬美元）</label><input id="calc-fcf" type="number" step="any" value="25"></div><div class="calc-result"><span>FCF MARGIN</span><output id="calc-result" aria-live="polite">25.0%</output><p>自由現金流 ÷ 營收 × 100%</p><small>僅作公式練習，不代表任何公司實績。</small></div></div>')
body+=section('questions','研究前，問自己四個問題',cards([('成長從哪裡來？','區分新客、擴充、價格、匯率與併購，避免把總成長當作有機需求。'),('合約有沒有轉成收入？','把 ARR、RPO 與後續營收一起追蹤，注意合約期間和產品定義。'),('現金流有什麼時點效果？','檢查預收款、應收帳款及資本支出，區分單季與全年數字。'),('每股價值是否改善？','獲利與 FCF 同時搭配 SBC、回購及稀釋股數，留意拆股口徑。')]))
body+=section('sources','定義與資料來源',sources([('CRWD：指標定義與調節表',source_urls['crwd'][-1]),('OKTA：指標定義與調節表',source_urls['okta'][-1]),('PANW：指標定義與調節表',source_urls['panw'][-1])]))
write('metrics/index.html',shell('metrics/index.html','讓數字，回到脈絡。','THE ANALYST TOOLKIT / 財報指標','從 ARR 到自由現金流，學會追蹤資安公司的成長品質與指標限制。',body,[('glossary','指標百科'),('calculator','互動練習'),('questions','研究問題'),('sources','定義來源')]))
write('assets/favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#102b30"/><text x="13" y="45" font-size="40" font-family="sans-serif" fill="#b8e3cd">C</text></svg>')
print('Built 7 pages.')
